package com.dawnrise.school.announcement;

import com.dawnrise.school.school.provisioning.IdentityProvisioningProperties;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import tools.jackson.core.type.TypeReference;
import tools.jackson.databind.ObjectMapper;
import com.dawnrise.school.communication.CommunicationAudienceService;
import com.dawnrise.school.communication.CommunicationDirectoryGateway;
import com.dawnrise.school.communication.CommunicationDtos;
import java.time.OffsetDateTime;import java.util.*;

@Component
public class SchoolNotificationRelayWorker {
 private final SchoolNotificationOutboxStore store;private final RestClient identity;private final RestClient academic;private final IdentityProvisioningProperties identityProperties;private final NotificationRelayProperties properties;private final ObjectMapper json;private final CommunicationAudienceService communicationAudiences;private final CommunicationDirectoryGateway communicationDirectory;
 public SchoolNotificationRelayWorker(SchoolNotificationOutboxStore store,@Qualifier("identityProvisioningRestClient") RestClient identity,@Qualifier("academicNotificationRestClient") RestClient academic,IdentityProvisioningProperties identityProperties,NotificationRelayProperties properties,ObjectMapper json,CommunicationAudienceService communicationAudiences,CommunicationDirectoryGateway communicationDirectory){this.store=store;this.identity=identity;this.academic=academic;this.identityProperties=identityProperties;this.properties=properties;this.json=json;this.communicationAudiences=communicationAudiences;this.communicationDirectory=communicationDirectory;}
 @Scheduled(fixedDelayString="${dawnrise.notification-relay.delay:PT10S}") public void deliver(){UUID owner=UUID.randomUUID();store.claim(owner,properties.getLease()).ifPresent(row->{try{Set<Long> recipients=resolve(row,owner);if(recipients.isEmpty())throw new IllegalStateException("Audience resolved to no active recipients");boolean leave=row.eventType().startsWith("LEAVE_");boolean conversation=row.eventType().equals("PARENT_COMMUNICATION_MESSAGE");String action=conversation?"COMMUNICATION_THREAD":row.sourceEventId().startsWith("leave-policy:")?"LEAVE_POLICY":leave?"LEAVE_REQUEST":row.eventType().equals("DAWNRISE_RELEASE")?"RELEASE_DETAILS":"ANNOUNCEMENT";IngestResponse response=identity.post().uri("/internal/v1/notification-events").headers(h->headers(h,identityProperties.getApiKey())).body(new Ingest(row.organizationId(),row.sourceEventId(),row.eventType(),leave?"LEAVE":"SCHOOL",row.importance(),row.heading(),row.context(),new Action(action,row.sourceId()),(conversation?"conversation:":row.sourceEventId().startsWith("leave-policy:")?"leave-policy:":leave?"leave:":row.eventType().toLowerCase()+":")+row.sourceId(),OffsetDateTime.now(),recipients,json.readValue(row.deliveryChannels(),new TypeReference<Set<String>>(){}))).retrieve().body(IngestResponse.class);if(response==null)throw new IllegalStateException("Identity notification ingestion returned no receipt");store.published(row.id(),owner);}catch(Exception e){store.failed(row.id(),owner,row.attemptCount()+1,properties.getMaxAttempts(),e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());}});}
 private Set<Long> resolve(SchoolNotificationOutboxStore.Row row,UUID owner)throws Exception{Set<Long> direct=json.readValue(row.recipientUserIds(),new TypeReference<Set<Long>>(){});if(!direct.isEmpty())return direct;if(row.senderUserId()!=null){var authority=communicationDirectory.senderAuthority(row.organizationId(),row.senderUserId());String required=row.schoolWideRequired()?"COMMUNICATION_NOTICE_SEND_SCHOOL_WIDE":"COMMUNICATION_NOTICE_SEND_SCOPED";if(!authority.active()||!authority.permissions().contains(required))throw new IllegalStateException("Sender is no longer authorized to deliver this notice");List<CommunicationDtos.Selection> selections=json.readValue(row.audienceSpec(),new TypeReference<List<CommunicationDtos.Selection>>(){});Set<Long> resolved=communicationAudiences.resolveRecipients(row.organizationId(),row.senderUserId(),row.schoolWideRequired(),selections);store.acceptRecipientSet(row,owner,json.writeValueAsString(resolved),resolved.size());return resolved;}return resolveLegacy(row);}
 private Set<Long> resolveLegacy(SchoolNotificationOutboxStore.Row row)throws Exception{List<Audience> audiences=json.readValue(row.audienceSpec(),new TypeReference<List<Audience>>(){});List<Audience> nativeAudience=audiences.stream().filter(a->!Set.of("WING","GRADE","SECTION").contains(a.type())).toList();Set<Long> result=new HashSet<>();if(!nativeAudience.isEmpty()){AudienceResponse r=identity.post().uri("/internal/v1/organizations/{org}/notification-audience/resolve",row.organizationId()).headers(h->headers(h,identityProperties.getApiKey())).body(new AudienceRequest(nativeAudience)).retrieve().body(AudienceResponse.class);if(r!=null)result.addAll(r.userIds());}for(Audience a:audiences)if(Set.of("WING","GRADE","SECTION").contains(a.type())){AcademicResponse r=academic.get().uri("/internal/v1/organizations/{org}/notification-audience/{type}/{id}",row.organizationId(),a.type(),Long.parseLong(a.key())).headers(h->headers(h,properties.getApiKey())).retrieve().body(AcademicResponse.class);if(r!=null)result.addAll(r.studentUserIds());}return result;}
 private void headers(org.springframework.http.HttpHeaders h,String key){h.set("X-Internal-Api-Key",key);h.set("X-Service-Name","school-service");}
 record Audience(String type,String key){} record AudienceRequest(List<Audience> audiences){} record AudienceResponse(Set<Long> userIds){} record AcademicResponse(Set<Long> studentUserIds){} record Action(String type,long referenceId){} record Ingest(long organizationId,String sourceEventId,String eventType,String category,String importance,String heading,String context,Action action,String groupingKey,OffsetDateTime occurredAt,Set<Long> recipientUserIds,Set<String> deliveryChannels){}
 record IngestResponse(UUID eventId,boolean created,int recipientCount){}
}
